import sympy
from sympy import S
import math

# Top-level setup: named object bindings that the witness expression may reference.
Z = S.Integers
Q = S.Rationals
R = S.Reals
C = S.Complexes

def Z_n(n):
    """Represents the module Z/nZ"""
    return n

def Ideal(n):
    """Represents the ideal generated by n"""
    return n

def QuotientModule(n):
    """Represents the quotient module Z/nZ"""
    return n

def VectorSpace(dim):
    """Represents a vector space of given dimension"""
    return dim

def conditions(witness):
    """
    Checks if the witness satisfies the remaining hypotheses and falsifies the conclusion.
    The witness is expected to be a tuple (R, m, M) or a dictionary with keys 'R', 'm', 'M'.
    For R = Z, m is the generator of the ideal, and M is n for Z/nZ (or 0 for Z).
    For R = Q/R/C, m is the generator of the ideal (0 or 1), and M is the vector space dimension.
    """
    try:
        if isinstance(witness, (tuple, list)) and len(witness) == 3:
            R_obj, m_obj, M_obj = witness
        elif isinstance(witness, dict):
            R_obj = witness.get('R')
            m_obj = witness.get('m')
            M_obj = witness.get('M')
        else:
            return [False, False, False, False]

        # Parse R
        R_str = str(R_obj)
        is_Z = R_str in ['Z', 'Integers', 'ZZ']
        is_field = R_str in ['Q', 'R', 'C', 'Rationals', 'Reals', 'Complexes', 'QQ', 'RR', 'CC']

        # Parse m
        m_val = None
        if isinstance(m_obj, (int, sympy.Integer)):
            m_val = int(m_obj)
        elif hasattr(m_obj, 'gen'):
            m_val = int(m_obj.gen)
        elif isinstance(m_obj, dict) and 'gen' in m_obj:
            m_val = int(m_obj['gen'])
            
        if m_val is None:
            m_str = str(m_obj)
            if m_str in ['Z', 'Integers', 'ZZ', 'S.Integers']:
                m_val = 1
            elif m_str in ['Q', 'R', 'C', 'Rationals', 'Reals', 'Complexes', 'QQ', 'RR', 'CC', 'S.Rationals', 'S.Reals', 'S.Complexes']:
                m_val = 1

        # Parse M
        M_val = None
        if isinstance(M_obj, (int, sympy.Integer)):
            M_val = int(M_obj)
        elif hasattr(M_obj, 'n'):
            M_val = int(M_obj.n)
        elif hasattr(M_obj, 'dim'):
            M_val = int(M_obj.dim)
        elif isinstance(M_obj, dict):
            if 'n' in M_obj:
                M_val = int(M_obj['n'])
            elif 'dim' in M_obj:
                M_val = int(M_obj['dim'])
        
        if M_val is None:
            M_str = str(M_obj)
            if M_str in ['Z', 'Integers', 'ZZ', 'S.Integers']:
                M_val = 0
            elif M_str in ['Q', 'R', 'C', 'Rationals', 'Reals', 'Complexes', 'QQ', 'RR', 'CC', 'S.Rationals', 'S.Reals', 'S.Complexes']:
                M_val = 1

        h1 = is_Z or is_field
        h2 = False
        h3 = False
        neg_q = False

        if is_Z:
            if m_val is not None and M_val is not None:
                h2 = True  # Z/nZ is finitely generated
                if M_val == 0:
                    h3 = (abs(m_val) == 1)
                    neg_q = True
                else:
                    h3 = (math.gcd(m_val, M_val) == 1)
                    neg_q = (abs(M_val) != 1)
                    
        elif is_field:
            if m_val is not None and M_val is not None:
                if M_val >= 0:
                    h2 = True  # Finite dimensional vector space is finitely generated
                    if m_val != 0:
                        h3 = True
                    else:
                        h3 = (M_val == 0)
                    neg_q = (M_val > 0)

        return [bool(h1), bool(h2), bool(h3), bool(neg_q)]
    except Exception:
        return [False, False, False, False]

CONDITION_LABELS = [
    "H_1: R is a commutative ring",
    "H_2: M is a finitely generated R-module",
    "H_3: mM = M",
    "¬Q: M is not the zero module"
]

N_HYP = 3
NEG_Q_INDEX = 3